import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportServlet extends HttpServlet {

    private static final Map<String, String> TEMPLATE_QUERIES = new HashMap<>();
    static {
        TEMPLATE_QUERIES.put("sales", "SELECT region, amount, quarter FROM sales_data WHERE year = ${year} AND region IN (${regions})");
        TEMPLATE_QUERIES.put("inventory", "SELECT sku, warehouse, qty FROM inventory WHERE category = '${category}'");
        TEMPLATE_QUERIES.put("audit", "SELECT user_id, action, ts FROM audit_log WHERE ts > '${start_date}' ORDER BY ts DESC LIMIT ${limit}");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        String reportType = req.getParameter("report_type");
        if (reportType == null || !TEMPLATE_QUERIES.containsKey(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Collect user-supplied parameters for template substitution
        Map<String, String> params = new HashMap<>();
        Enumeration<String> paramNames = req.getParameterNames();
        while (paramNames.hasMoreElements()) {
            String name = paramNames.nextElement();
            if (!name.equals("report_type")) {
                String value = req.getParameter(name);
                // Basic sanitization - remove comments and semicolons
                value = value.replaceAll("--", "").replaceAll(";", "");
                params.put(name, value);
            }
        }

        String template = TEMPLATE_QUERIES.get(reportType);
        StringSubstitutor sub = new StringSubstitutor(params);
        String finalQuery = sub.replace(template);

        // Log for debugging
        System.out.println("[ReportServlet] Executing: " + finalQuery);

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = getConnection();
            stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(finalQuery);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write(resultSetToJson(rs));
            out.flush();
        } catch (SQLException e) {
            resp.sendError(500, "Query failed: " + e.getMessage());
        } finally {
            if (stmt != null) try { stmt.close(); } catch (SQLException ignored) {}
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        List<Map<String, Object>> rows = new ArrayList<>();
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        while (rs.next()) {
            Map<String, Object> row = new LinkedHashMap<>();
            for (int i = 1; i <= cols; i++) {
                row.put(meta.getColumnLabel(i), rs.getObject(i));
            }
            rows.add(row);
        }
        // Simple JSON serialization
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < rows.size(); i++) {
            if (i > 0) sb.append(",");
            sb.append("{");
            int j = 0;
            for (Map.Entry<String, Object> e : rows.get(i).entrySet()) {
                if (j++ > 0) sb.append(",");
                sb.append("\"").append(e.getKey()).append("\":");
                if (e.getValue() instanceof Number) sb.append(e.getValue());
                else sb.append("\"").append(String.valueOf(e.getValue()).replace("\"", "\\\"")).append("\"");
            }
            sb.append("}");
        }
        sb.append("]");
        return sb.toString();
    }
}
